def get_nested_value(data, path):
    if not path:
        return data if isinstance(data, dict) else None

    # Split path by dots, but we need to handle keys that contain dots
    # Since keys are case-insensitive and may contain dots, we cannot simply split by '.'
    # We must try to match keys step by step, considering case-insensitivity.

    keys = path.split('.')
    current = data

    for key in keys:
        if not isinstance(current, dict):
            return None

        # Find a key in current that matches the target key (case-insensitive)
        found_key = None
        for k in current:
            if k.lower() == key.lower():
                found_key = k
                break

        if found_key is None:
            return None

        current = current[found_key]

    return current
```

