def is_magic_square(square):
    # Check if input is a 4x4 grid
    if not isinstance(square, list) or len(square) != 4:
        return False
    for row in square:
        if not isinstance(row, list) or len(row) != 4:
            return False

    # Check if numbers are distinct and in range 1 to 16
    nums = set()
    for row in square:
        for num in row:
            if not isinstance(num, int) or num < 1 or num > 16:
                return False
            if num in nums:
                return False
            nums.add(num)
    if len(nums) != 16:
        return False

    # Calculate the expected magic constant
    # For a 4x4 magic square with numbers 1 to 16, the sum is 34
    magic_sum = sum(range(1, 17)) // 4

    # Check row sums
    for row in square:
        if sum(row) != magic_sum:
            return False

    # Check column sums
    for col_idx in range(4):
        col_sum = sum(square[row][col_idx] for row in range(4))
        if col_sum != magic_sum:
            return False

    # Check main diagonal sum
    main_diag_sum = sum(square[i][i] for i in range(4))
    if main_diag_sum != magic_sum:
        return False

    # Check secondary diagonal sum
    secondary_diag_sum = sum(square[i][3 - i] for i in range(4))
    if secondary_diag_sum != magic_sum:
        return False

    return True
```

