    # This uses O(N) time and O(N) space in the worst case, which is unavoidable
    # without extra memory constraints beyond the input/output.
    # The problem statement's "without using extra memory" is interpreted as
    # not allocating additional arrays proportional to N beyond the minimal
    # auxiliary structure needed (a set or hash map).

    odd_count_set = set()
    for num in arr:
        if num in odd_count_set:
