    required_keys = ["name", "age", "address", "phone_number"]
    if not all(key in data for key in required_keys):
        return False

    # Validate "name": string of at least 2 characters
    if not isinstance(data["name"], str) or len(data["name"]) < 2:
        return False

    # Validate "age": positive integer
    if not isinstance(data["age"], int) or isinstance(data["age"], bool) or data["age"] <= 0:
