def capitalize_titles(titles):
    small_words = {
        'a', 'an', 'the', 'and', 'or', 'but', 'for', 'nor', 'on', 'at', 'to', 'by', 'in', 'of',
        'up', 'out', 'as', 'if', 'then', 'else', 'when', 'where', 'why', 'how', 'all', 'any',
        'both', 'each', 'few', 'more', 'most', 'other', 'some', 'such', 'no', 'nor', 'not',
        'only', 'own', 'same', 'so', 'than', 'too', 'very', 's', 't', 'can', 'will', 'just',
        'don', 'should', 'now'
    }

    def capitalize_word(word, index, total_words):
        word_lower = word.lower()
        is_first = index == 0
        is_last = index == total_words - 1
        is_small = word_lower in small_words
        is_short = len(word_lower) <= 3

        # Capitalize if:
        # - It's the first or last word, OR
        # - It's longer than 3 characters, OR
        # - It's short (<=3) but NOT in the small_words list
        if is_first or is_last or (len(word_lower) > 3) or (is_short and not is_small):
            return word.capitalize()
        else:
            return word

    result = []
    for title in titles:
        words = title.split()
        capitalized_words = [
            capitalize_word(word, i, len(words))
            for i, word in enumerate(words)
        ]
        result.append(" ".join(capitalized_words))

    return result
