# Global registry to store registered functions
_function_registry = {}

def register_function(name=None):
    """
    Decorator to register a function into a global registry.

    - If 'name' is provided, it uses that as the function's registry key.
    - If 'name' is not provided, it uses the function's own __name__.
    - Raises ValueError if a function with the same name is already registered.

    Usage:
        @register_function
        def my_func():
            pass

        @register_function("custom_name")
        def another_func():
            pass
    """
    def decorator(func):
        # Determine the name to use for registration
        if name is None:
            reg_name = func.__name__
        else:
            reg_name = name

        # Check for duplicate registration
        if reg_name in _function_registry:
            raise ValueError(f"Function with name '{reg_name}' is already registered.")

        # Register the function
        _function_registry[reg_name] = func
        return func

    return decorator
```

