def normalize_sensor_name(sName: str) -> str:
    # Extract the label part: alphabetic characters only, in order of appearance
    label_chars = []
    for ch in sName:
        if ch.isalpha():
            label_chars.append(ch)
        elif ch.isspace():
            # Stop reading label once we hit a space (or any non-alpha)
            break
        else:
            # Non-alpha, non-space stops label extraction
            break
    label = ''.join(label_chars).upper().replace(' ', '')

    # Extract the number part: digits only, after the label and any separator
    # We look for the first digit after the label section
    number_chars = []
    found_digit = False
    for ch in sName:
        if ch.isdigit():
            number_chars.append(ch)
            found_digit = True
        elif not found_digit:
            # Before first digit, ignore non-digits (including spaces)
            continue
        else:
            # After first digit, stop if we hit a non-digit
            break

    if not number_chars:
        # No number found; return just the label with a placeholder? 
        # Based on spec, we assume a number exists. If not, return label with "00"
        number = "00"
    else:
        number = ''.join(number_chars)

    # Ensure number has at least two digits with leading zero if needed
    if len(number) < 2:
        number = number.zfill(2)

    return f"{label} {number}"
