def bytes_to_human(bytes):
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'YB']
    unit_index = 0
    value = float(bytes)

    while unit_index < len(units) - 1 and value >= 1024:
        value /= 1024
        unit_index += 1

    if value >= 1024:
        value = round(value)
    else:
        if value >= 1023.5:
