def custom_sort_words(words):
    # Count frequencies manually
    freq = {}
    for w in words:
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1

    # Build list of (word, frequency)
    items = []
    for w in words:
        items.append((w, freq[w]))

    # Implement a simple selection sort based on the custom criteria
    n = len(items)
    for i in range(n - 1):
        # Assume current position i has the best element
        best_idx = i
        best_word, best_freq = items[i]

        for j in range(i + 1, n):
            w, f = items[j]
            # Compare: higher frequency first, then alphabetically smaller
            if f > best_freq:
                best_idx = j
                best_word, best_freq = w, f
            elif f == best_freq:
                if w < best_word:
                    best_idx = j
                    best_word, best_freq = w, f

        # Swap if needed
