def compare_intervals(x, y, chr_order):
    # Handle None cases
    if x is None and y is None:
        return 0
    if x is None:
        return -1
    if y is None:
        return 1

    # Extract components
    chr_x, start_x, end_x = x
    chr_y, start_y, end_y = y

    # Compare chromosomes using their order
    if chr_x == chr_y:
        # Same chromosome: compare start positions
        if start_x < start_y:
            return 1
        if start_x > start_y:
            return 0
        # Start positions equal: compare end positions
        if end_x <= end_y:
            return 1
        else:
            return 0
    else:
        # Different chromosomes: compare their order in chr_order
        order_x = chr_order.get(chr_x, float('inf'))
        order_y = chr_order.get(chr_y, float('inf'))

        if order_x < order_y:
            return 1
        elif order_x > order_y:
            return 0
        else:
            # Should not happen if chr_order is consistent, but handle safely
