def is_palindrome(s):
    def is_alnum(c):
        # Check if character is alphanumeric without using built-in isalnum
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')

    def to_lower(c):
        # Convert uppercase to lowercase manually
        if 'A' <= c <= 'Z':
            return chr(ord(c) + 32)
        return c

    def helper(left, right):
        # Base case: pointers have crossed or met
        if left >= right:
            return True

        # Move left pointer to next alphanumeric character
        while left < right and not is_alnum(s[left]):
            left += 1

        # Move right pointer to previous alphanumeric character
        while left < right and not is_alnum(s[right]):
            right -= 1

        # If pointers crossed during skipping, it's a palindrome
        if left >= right:
            return True

        # Compare characters (case-insensitive)
        l_char = to_lower(s[left])
        r_char = to_lower(s[right])

        if l_char != r_char:
            return False

        return helper(left + 1, right - 1)

    return helper(0, len(s) - 1)
```

