def prime_generator(n):
    """
    Generates all prime numbers less than n using the Sieve of Eratosthenes.
    Yields primes one by one.

    Constraints: 2 <= n <= 10^6
    """
    if n <= 2:
        return

    # Initialize boolean array: True means "potentially prime"
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    # Sieve of Eratosthenes
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            # Mark multiples of i starting from i*i
            for multiple in range(i * i, n, i):
                is_prime[multiple] = False

    # Yield all numbers marked as prime
    for num in range(2, n):
        if is_prime[num]:
            yield num
