    import ipaddress

    # Determine the network address based on input format
    if '/' in network:
        # CIDR notation: network is like '192.168.1.0/24'
        net_obj = ipaddress.ip_network(network, strict=False)
    else:
        # Subnet mask provided: network is like '192.168.1.1' and subnet is '255.255.255.0'
        if subnet:
            net_obj = ipaddress.ip_network(f"{network}/{subnet}", strict=False)
