def is_prime(n, known_primes=[2, 3, 5, 7, 11, 13, 17, 19]):
    if n < 2:
        return False
    if n in known_primes:
        return True
    if n * n < known_primes[-1] * known_primes[-1]:
        limit = int(n ** 0.5)
        for p in known_primes:
            if p > limit:
                break
            if n % p == 0:
                return False
        return True

    # Expand known_primes until we have enough to test up to sqrt(n)
    limit = int(n ** 0.5)
    while known_primes[-1] < limit:
        candidate = known_primes[-1] + 2
        while True:
            is_candidate_prime = True
            for p in known_primes:
                if p * p > candidate:
                    break
                if candidate % p == 0:
                    is_candidate_prime = False
                    break
            if is_candidate_prime:
                known_primes.append(candidate)
                break
            candidate += 2

    # Now check divisibility by all primes up to sqrt(n)
    limit = int(n ** 0.5)
    for p in known_primes:
        if p > limit:
            break
        if n % p == 0:
            return False

    return True
