def flatten_and_filter(l: list) -> list:
    # Manual flattening
    flat = []
    for sublist in l:
        for item in sublist:
            flat.append(item)

    # Manual deduplication while preserving first occurrence order
    seen = []
    for num in flat:
        is_duplicate = False
        for existing in seen:
            if existing == num:
                is_duplicate = True
                break
        if not is_duplicate:
            seen.append(num)

    # Manual sorting (ascending) using simple insertion sort
    result = seen[:]
    n = len(result)
    for i in range(1, n):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key

    return result
