def _filter_datasets_by_kernel_scheme_property(datasets, kernel, scheme, property):
    if not datasets:
        return []
    first, *rest = datasets
    if not isinstance(first, dict) or kernel not in first:
        return _filter_datasets_by_kernel_scheme_property(rest, kernel, scheme, property)
    kernel_data = first[kernel]
    if not isinstance(kernel_data, dict) or scheme not in kernel_data:
        return _filter_datasets_by_kernel_scheme_property(rest, kernel, scheme, property)
    scheme_data = kernel_data[scheme]
    if not isinstance(scheme_data, dict) or property not in scheme_data:
        return _filter_datasets_by_kernel_scheme_property(rest, kernel, scheme, property)
    return [first] + _filter_datasets_by_kernel_scheme_property(rest, kernel, scheme, property)

def _extract_runtimes_and_norms(filtered_datasets, runtimes, kernel, scheme, property, norm):
    if not filtered_datasets:
        return [], []
    first, *rest = filtered_datasets
    dataset_key = list(first.keys())[0]
    runtime_value = runtimes.get(dataset_key, {}).get(kernel, {}).get(scheme, 0)
    values_list = first[kernel][scheme].get(property, [])
    norm_value = values_list[norm] if norm < len(values_list) else 0.0
    runtimes_list = [runtime_value / 1000000.0]
    norms_list = [norm_value]
    return runtimes_list + _extract_runtimes_and_norms(rest, runtimes, kernel, scheme, property, norm), norms_list + _extract_runtimes_and_norms(rest, runtimes, kernel, scheme, property, norm)[1]

def extract_info(data, runtimes, kernel, scheme, property, norm):
    filtered = _filter_datasets_by_kernel_scheme_property(list(data.keys()), kernel, scheme, property)
    runtimes_list, norms_list = _extract_runtimes_and_norms(filtered, runtimes, kernel, scheme, property, norm)
    return runtimes_list, norms_list
