from typing import List, Optional

class TreeNode:
    def __init__(self, value: int, left: 'Optional[TreeNode]' = None, right: 'Optional[TreeNode]' = None):
        self.value = value
        self.left = left
        self.right = right

def level_order_traversal(root: Optional[TreeNode]) -> List[int]:
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        result.append(node.value)

        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    return result
