def find_wake_up_days(D, N, T, knocks):
    result = []
    for day_idx, day_knocks in enumerate(knocks, start=1):
        # Find the longest strictly increasing subsequence length
        # We only need to know if there exists a subsequence of length > T
        # Use patience sorting / LIS O(N log N) approach

        tails = []  # tails[i] = smallest tail of all increasing subsequences of length i+1
        for x in day_knocks:
            # Binary search for the first element in tails >= x
            left, right = 0, len(tails)
            while left < right:
                mid = (left + right) // 2
                if tails[mid] < x:
                    left = mid + 1
                else:
                    right = mid
            if left == len(tails):
                tails.append(x)
            else:
                tails[left] = x

        if len(tails) > T:
            result.append(day_idx)

    return " ".join(map(str, result))
