def find_largest_prime_factor(n: int) -> int:
    if n <= 1:
        return n  # No prime factors for 0 or 1; return as-is per spec constraints (n >= 1)

    largest_prime = 1

    # Remove factor 2
    while n % 2 == 0:
        largest_prime = 2
        n //= 2

    # Check odd factors from 3 upwards
    f = 3
    while f * f <= n:
        while n % f == 0:
            largest_prime = f
            n //= f
        f += 2

    # If n is now greater than 1, it is a prime
    if n > 1:
        largest_prime = n

    return largest_prime
