```python
def is_fermat_prime(n: int) -> bool:
    if n <= 1:
        return False

    # Check if n is of the form 2^(2^k) + 1
    # That means n - 1 must be a power of 2, and the exponent must itself be a power of 2.
    m = n - 1
    if m <= 0:
        return False

    # Check if m is a power of 2
    if m & (m - 1) != 0:
        return False

    # Now m = 2^p, we need p to be a power of 2 (i.e., p = 2^k)
    # Find p such that 2^p = m
    p = 0
    temp = m
    while temp > 1:
        temp >>= 1
        p += 1

    # Check if p is a power of 2
    if p <= 0 or (p & (p - 1)) != 0:
        return False

    # Now we know n = 2^(2^k) + 1 for some non-negative integer k.
    # We must also verify that n is prime without using built-in primality tests.
    # Since n can be up to 10^18, we use a deterministic Miller-Rabin test
    # with bases sufficient for 64-bit integers.

    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x == 2 or x == 3:
            return True
        if x % 2 == 0:
            return False

        # Write x-1 as d * 2^s
        d = x - 1
        s = 0
        while d % 2 == 0:
            d //= 2
            s += 1

        # Deterministic bases for n < 2^64
