def count_prime_factors(n: int) -> int:
    count = 0
    d = 2

    # Check for factor 2 separately to allow stepping by 2 later
    if n % d == 0:
        count += 1
        while n % d == 0:
            n //= d

    d = 3
    # Iterate only up to sqrt(n)
    while d * d <= n:
        if n % d == 0:
            count += 1
            while n % d == 0:
                n //= d
        d += 2

    # If n is now greater than 1, it is a prime factor itself
    if n > 1:
        count += 1

    return count
