def hex_to_binary_to_string(hex_str: str) -> str:
    def hex_char_to_int(c: str) -> int:
        if '0' <= c <= '9':
            return ord(c) - ord('0')
        if 'a' <= c <= 'f':
            return ord(c) - ord('a') + 10
        if 'A' <= c <= 'F':
            return ord(c) - ord('A') + 10
        raise ValueError(f"Invalid hex character: {c}")

    def int_to_char(value: int) -> str:
        # value is guaranteed to be in 0..255 for valid ASCII
        return chr(value)

    result_chars = []
    i = 0
    n = len(hex_str)

    while i < n:
        high_nibble = hex_char_to_int(hex_str[i])
        low_nibble = hex_char_to_int(hex_str[i + 1])
        i += 2

        # Combine two nibbles into one byte using bitwise operations
        byte_value = (high_nibble << 4) | low_nibble

        result_chars.append(int_to_char(byte_value))

    return ''.join(result_chars)
