from typing import List

def levenshtein_distance(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    # Create a matrix to store distances
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )
    return dp[m][n]

def find_closest_word(words: List[str], target: str) -> str:
    min_dist = float('inf')
    closest_word = None

    for word in words:
        dist = levenshtein_distance(word, target)
        if dist < min_dist:
            min_dist = dist
            closest_word = word
        # If distances are equal, we keep the earlier word (do nothing)

    return closest_word if closest_word is not None else ""
```

