def is_parabola(points):
    # Empty list is considered valid
    if not points:
        return True

    # We need to find a positive constant a such that y = a * x^2 for all points.
    # First, filter out points where x is 0. If there's a point (0, y) with y != 0,
    # it cannot lie on y = a*x^2 (since that would require y=0).
    for x, y in points:
        if x == 0:
            if y != 0:
                return False

    # If all points have x == 0 and y == 0, they all lie on the parabola (degenerate case with any a)
    # But since we already checked x==0 implies y==0, we can proceed.

    # Compute a from the first point with non-zero x
    a = None
    for x, y in points:
        if x != 0:
            a = y / (x ** 2)
            break

    # If no point has non-zero x, then all points are (0, 0), which satisfies y = a*x^2 for any a > 0
    if a is None:
        return True

    # Check that a is positive
    if a <= 0:
        return False

    # Verify all points satisfy y = a * x^2
    for x, y in points:
        expected_y = a * (x ** 2)
        # Use a small tolerance for floating point comparisons
        if abs(y - expected_y) > 1e-9:
            return False

    return True
