def find_largest_prime_factor(numbers):
    def largest_prime_factor(n):
        if n == 1:
            return None

        last_prime = None
        d = 2

        # Handle factor 2 separately to allow skipping even numbers later
        while d * d <= n:
            while n % d == 0:
                last_prime = d
                n //= d
            d += 1 if d == 2 else 2  # After 2, skip even numbers

        # If n > 1 after the loop, then the remaining n is a prime
        if n > 1:
            last_prime = n

        return last_prime

