def count_event_repetitions(event_names):
    from collections import defaultdict
    import re

    counts = defaultdict(int)

    for event in event_names:
        # Extract the base event name by removing trailing "[N]" if present
        match = re.search(r'\s*\[\d+\]\s*$', event)
        if match:
            base_event = event[:match.start()].strip()
        else:
            base_event = event.strip()

        counts[base_event] += 1

    # Filter out events that were held only once
    return {event: count for event, count in counts.items() if count > 1}
