def max_gcd_after_removal(numbers):
    n = len(numbers)
    if n < 2:
        return 0

    # Precompute GCD of all pairs without using built-in gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    max_g = 0

    # Try removing each element one by one
    for i in range(n):
        # Collect the remaining numbers
        remaining = []
        for j in range(n):
            if i != j:
                remaining.append(numbers[j])

        # Compute GCD of all remaining numbers
        current_g = remaining[0]
        for k in range(1, len(remaining)):
            current_g = gcd(current_g, remaining[k])
            if current_g == 1:
                break  # GCD cannot get larger than 1

        if current_g > max_g:
            max_g = current_g

    return max_g
