import math
from functools import reduce

def calculate_lcm(*args):
    # If any argument is 0, LCM is defined as 0
    if any(x == 0 for x in args):
        return 0

    # Work with absolute values to handle negatives, then ensure result is positive
    numbers = [abs(x) for x in args]

    # LCM of two numbers: lcm(a, b) = abs(a * b) // gcd(a, b)
    def lcm_pair(a, b):
        return (a * b) // math.gcd(a, b)

    return reduce(lcm_pair, numbers)
