def has_cycle(graph):
    """
    Determines whether a directed graph contains a cycle.

    Args:
        graph (dict): Adjacency list where keys are nodes (0 to n-1)
                      and values are lists of adjacent nodes.

    Returns:
        bool: True if the graph contains a cycle, False otherwise.
    """
    # Ensure all nodes from 0 to n-1 are present in the graph
    # (in case some nodes have no outgoing edges and thus are missing as keys)
    nodes = set(graph.keys())
    for neighbors in graph.values():
        nodes.update(neighbors)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in nodes}

    def dfs(node):
        color[node] = GRAY
        for neighbor in graph.get(node, []):
            if color[neighbor] == GRAY:
                return True  # Back edge found -> cycle
            if color[neighbor] == WHITE and dfs(neighbor):
                return True
        color[node] = BLACK
        return False

    for node in nodes:
        if color[node] == WHITE:
            if dfs(node):
                return True
    return False
