def compress_strings(strings):
    def compress(s):
        if not s:
            return ""
        result = []
        count = 1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                count += 1
            else:
                if count > 1:
                    result.append(s[i - 1] + str(count))
                else:
                    result.append(s[i - 1])
                count = 1
        # Append the last group
        if count > 1:
            result.append(s[-1] + str(count))
        else:
            result.append(s[-1])
        return "".join(result)

    return [compress(s) for s in strings]
