def prime_sum(N):
    if N <= 0:
        return 0

    # Estimate upper bound for the N-th prime using Rosser's theorem:
    # p_n < n (ln n + ln ln n) for n >= 6
    if N < 6:
        # Small N handled directly
        primes = []
        for i in range(2, 15):
            if is_prime(i):
                primes.append(i)
                if len(primes) == N:
                    break
        return sum(primes)

    # Upper bound estimate
    import math
    bound = int(N * (math.log(N) + math.log(math.log(N)))) + 10

    primes = []
    for num in range(2, bound + 1):
        if is_prime(num):
            primes.append(num)
            if len(primes) == N:
                break

    return sum(primes)


def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.isqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
