def get_unique_element(lst):
    if not lst:
        raise ValueError("No unique element found in the list.")

    # First pass: identify candidates that appear only once so far
    # We'll store indices of elements seen once; if seen again, remove from candidates
    seen_once = []
    seen_twice = set()

    for i, val in enumerate(lst):
        if val in seen_once:
            # This element appeared twice now; remove from once list
            if val in seen_once:
                seen_once.remove(val)
            seen_twice.add(val)
        elif val not in seen_twice:
            seen_once.append(val)

    # After first pass, seen_once contains elements that appeared exactly once
    if not seen_once:
        raise ValueError("No unique element found in the list.")

    # Check if there are multiple unique elements
    if len(seen_once) > 1:
        print("Multiple unique elements found. Returning the first one.")

    # Find the first occurrence of any element in seen_once
    for val in seen_once:
        if val in lst:
            return val

    # Fallback (should not be reached if logic is correct)
    raise ValueError("No unique element found in the list.")
