def remove_whitespace(s):
    # Find the first non-whitespace index from the start
    start = 0
    while start < len(s) and s[start].isspace():
        start += 1

    # Find the first non-whitespace index from the end
    end = len(s)
    while end > start and s[end - 1].isspace():
        end -= 1

    # Return the sliced string
    return s[start:end]
