def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True

    left, right = 1, n // 2

    while left <= right:
        mid = (left + right) // 2
        square = mid * mid

        if square == n:
            return True
        elif square < n:
            left = mid + 1
        else:
            right = mid - 1

    return False
