def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return n  # By constraint n >= 1, but handle 1 gracefully

    # Remove factors of 2
    while n % 2 == 0:
        largest = 2
        n //= 2

    # Check odd factors from 3 upwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            largest = i
            n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        largest = n

    return largest
