def update_highest_temperature(new_temperature):
    import os
    import tempfile
    import shutil

    file_path = "highest_temperature.txt"

    # Read current highest temperature
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            try:
                current_highest = float(f.read().strip())
            except ValueError:
                current_highest = float("-inf")
    else:
        current_highest = float("-inf")

    # Determine if update is needed
    if new_temperature > current_highest:
        # Perform atomic update using a temporary file
        temp_fd, temp_path = tempfile.mkstemp(dir=os.path.dirname(file_path) or ".")
        try:
            with os.fdopen(temp_fd, "w") as f:
                f.write(str(new_temperature))
            shutil.move(temp_path, file_path)
        except Exception:
            # Clean up temp file on failure
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            raise
        return new_temperature
    else:
