def matrix_multiply(A, B):
    # Validate dimensions
    if not A or not B:
        raise ValueError("Matrices cannot be empty.")

    m = len(A)
    n = len(A[0])
    p = len(B[0])

    # Check if number of columns in A equals number of rows in B
    if n != len(B):
        raise ValueError("Number of columns in A must equal number of rows in B.")

    # Check consistency of rows in A and columns in B
    for i in range(m):
        if len(A[i]) != n:
            raise ValueError("All rows in A must have the same number of columns.")
    for j in range(p):
        if len(B[j]) != n:
            raise ValueError("All rows in B must have the same number of columns.")

    # Initialize result matrix C of size m x p with zeros
    C = [[0 for _ in range(p)] for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]

    return C
