def longest_palindromic_substring(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    if n == 1:
        return 1

    # dp[i][j] will be True if s[i:j+1] is a palindrome
    dp = [[False] * n for _ in range(n)]
    max_len = 1

    # All substrings of length 1 are palindromes
    for i in range(n):
        dp[i][i] = True

    # Check for substrings of length 2
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            max_len = 2

    # Check for substrings of length >= 3
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and dp[i + 1][j - 1]:
                dp[i][j] = True
                max_len = length

    return max_len
```

