    stack = [-1]  # Initialize with -1 as the base for calculating lengths

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                # If stack is empty, push current index as new base
                stack.append(i)
