def find_phrase_occurrences(source_text, target_phrase):
    # Predefined synonym dictionary (example; extend as needed)
    synonyms = {
        "quick": ["fast", "rapid", "swift"],
        "brown": ["chestnut", "tawny"],
        "fox": ["red fox", "vulpine"],
        "the": ["a", "an"],
        "lazy": ["sluggish", "idle"],
        "dog": ["canine", "hound"],
        "jumps": ["leaps", "springs"],
        "over": ["above", "across"],
        "source_text": ["input", "text"],
        "target_phrase": ["query", "phrase"],
    }

    def is_synonym(word, candidate):
        # Check exact match
        if word == candidate:
            return True
        # Check if candidate is a synonym of word
        if word in synonyms:
            if candidate in synonyms[word]:
                return True
        # Check if word is a synonym of candidate (reverse lookup)
        if candidate in synonyms:
            if word in synonyms[candidate]:
                return True
        return False

    def words_match(w1, w2):
        return is_synonym(w1, w2)

    n = len(source_text)
    m = len(target_phrase)

    if m == 0:
        return (False, [], [], [])

    occurrences = []

    for i in range(n - m + 1):
        match = True
        matched_words = []
        for j in range(m):
            if not words_match(target_phrase[j], source_text[i + j]):
                match = False
                break
            matched_words.append(source_text[i + j])
        if match:
            occurrences.append((i, i + m - 1, matched_words))

    if not occurrences:
        return (False, [], [], [])

    start_indices = [occ[0] for occ in occurrences]
    end_indices = [occ[1] for occ in occurrences]
    matched_word_lists = [occ[2] for occ in occurrences]

    return (True, start_indices, end_indices, matched_word_lists)
