def infix_to_postfix(expression):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    stack = []

    i = 0
    n = len(expression)

    while i < n:
        char = expression[i]

        if char.isdigit():
            # Handle multi-digit numbers
            num = ""
            while i < n and expression[i].isdigit():
                num += expression[i]
                i += 1
            output.append(num)
            continue  # do not increment i again in the main loop

        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # remove '('
        elif char in precedence:
            while (stack and stack[-1] != '(' and
                   precedence.get(stack[-1], 0) >= precedence[char]):
                output.append(stack.pop())
            stack.append(char)
        i += 1

    while stack:
        output.append(stack.pop())

    return " ".join(output)
