def recursive_power(base, exponent):
    # Base case: exponent is 0
    if exponent == 0:
        return 1

    # Base case: exponent is 1
    if exponent == 1:
        return base

    # Handle negative exponent
    if exponent < 0:
        return 1 / recursive_power(base, -exponent)

    # Recursive case: base^(n) = base * base^(n-1)
    # We avoid using '*' directly by using addition in the recursive step logic
    # But since we cannot use '*', we must simulate multiplication via recursion
    # However, the problem says: "recursively call itself with the base added to itself the number of times specified by the exponent minus one"
    # This implies: base^exponent = base + base + ... + base (exponent times) -> but that's addition, not power.
    # Re-reading: "recursively call itself with the base added to itself the number of times specified by the exponent minus one"
    # This is ambiguous, but logically for power without *, we must do:
    # base^exponent = base * base^(exponent-1), and simulate multiplication via repeated addition recursively.

    # Let's define a helper to compute base * exponent_value using repeated addition recursively
    def multiply(a, b):
        if b == 0:
            return 0
        if b == 1:
            return a
        if b < 0:
            return -multiply(a, -b)
        # a * b = a + (a * (b-1))
        return a + multiply(a, b - 1)

    # Now compute base * recursive_power(base, exponent - 1)
    return multiply(base, recursive_power(base, exponent - 1))
