def is_cyclic(graph):
    """
    Determines if a directed graph contains a cycle.

    Args:
        graph (dict): Adjacency list where keys are nodes and values are lists of adjacent nodes.

    Returns:
        bool: True if the graph contains a cycle, False otherwise.
    """
    # All nodes are from 0 to n-1, but we only consider nodes that appear as keys or in values
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in all_nodes}

    def dfs(node):
        color[node] = GRAY
        for neighbor in graph.get(node, []):
            if color[neighbor] == GRAY:
                return True  # Back edge found -> cycle
            if color[neighbor] == WHITE:
                if dfs(neighbor):
                    return True
        color[node] = BLACK
        return False

    for node in all_nodes:
        if color[node] == WHITE:
            if dfs(node):
                return True
    return False
