        depot_x, depot_y = depot['coordinates']
        found = False
        for nx, ny in nodes:
            dx = depot_x - nx
            dy = depot_y - ny
            if dx * dx + dy * dy <= r_sq:
                found = True
                break
        if not found:
            return False

    return True
```

