def count_balanced_brackets(s):
    stack = []
    pairs = []  # Each element: (open_index, close_index)

    for i, ch in enumerate(s):
        if ch == '[':
            stack.append(i)
        elif ch == ']':
            if not stack:
                return -1  # Unbalanced: extra closing bracket
            open_idx = stack.pop()
            pairs.append((open_idx, i))

    if stack:
        return -1  # Unbalanced: extra opening bracket

    # Now classify pairs as nested or non-nested
    # Sort pairs by open index (already in order due to traversal)
    # A pair (o1, c1) is nested inside (o2, c2) if o2 < o1 and c1 < c2
    # We'll count how many pairs are "non-nested" meaning no other pair fully contains them.

    n = len(pairs)
    if n == 0:
        return [0, 0]

    # For each pair, check if there exists another pair that contains it
    non_nested_count = 0
    nested_count = 0

    for i in range(n):
        o1, c1 = pairs[i]
        is_nested = False
        for j in range(n):
            if i == j:
                continue
            o2, c2 = pairs[j]
            # Check if pair j contains pair i
            if o2 < o1 and c1 < c2:
                is_nested = True
                break
        if is_nested:
            nested_count += 1
        else:
            non_nested_count += 1

    return [non_nested_count, nested_count]
